BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),base AS MATERIALIZED(SELECT s.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),r AS(SELECT a.ts_code,bool_or(r.report_type='1') has_type1,bool_or(r.report_type='4') has_type4,bool_or(r.report_type='4' AND r.n_income_attr_p IS NOT NULL) type4_metric_nonnull,bool_or(r.report_type='4' AND r.ann_date>DATE '2021-10-31') type4_announced_after_oct2021 FROM base a JOIN raw_tushare.income r ON r.ts_code=a.ts_code WHERE r.end_date=DATE '2021-09-30' AND r.report_type IN('1','4') GROUP BY a.ts_code),q AS(SELECT count(*) type1_or4_codes,count(*) FILTER(WHERE has_type1) type1_codes,count(*) FILTER(WHERE has_type4) type4_codes,count(*) FILTER(WHERE NOT has_type1 AND has_type4) only_type4_codes,count(*) FILTER(WHERE NOT has_type1 AND type4_metric_nonnull) only_type4_metric_nonnull,count(*) FILTER(WHERE type4_announced_after_oct2021) type4_after_historical_cutoff FROM r)
SELECT jsonb_build_object('section','income_2021_adjusted_candidate','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),base AS MATERIALIZED(SELECT s.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),r AS(SELECT a.ts_code,bool_or(r.report_type='1') has_type1,bool_or(r.report_type='4') has_type4,bool_or(r.report_type='4' AND r.n_cashflow_act IS NOT NULL) type4_metric_nonnull,bool_or(r.report_type='4' AND r.ann_date>DATE '2021-10-31') type4_announced_after_oct2021 FROM base a JOIN raw_tushare.cashflow r ON r.ts_code=a.ts_code WHERE r.end_date=DATE '2021-09-30' AND r.report_type IN('1','4') GROUP BY a.ts_code),q AS(SELECT count(*) type1_or4_codes,count(*) FILTER(WHERE has_type1) type1_codes,count(*) FILTER(WHERE has_type4) type4_codes,count(*) FILTER(WHERE NOT has_type1 AND has_type4) only_type4_codes,count(*) FILTER(WHERE NOT has_type1 AND type4_metric_nonnull) only_type4_metric_nonnull,count(*) FILTER(WHERE type4_announced_after_oct2021) type4_after_historical_cutoff FROM r)
SELECT jsonb_build_object('section','cashflow_2021_adjusted_candidate','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
BEGIN READ ONLY;
SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='3s'; SET LOCAL jit=off; SET LOCAL enable_nestloop=off;
WITH members AS MATERIALIZED(SELECT DISTINCT m.con_code AS ts_code FROM core_serving.dc_member m JOIN core_serving.dc_index i ON i.trade_date=m.trade_date AND i.ts_code=m.ts_code WHERE m.trade_date=DATE '2026-09-30' AND i.idx_type='行业板块' AND i.level='东财一级行业'),base AS MATERIALIZED(SELECT s.ts_code FROM members m JOIN raw_tushare.stock_basic s ON s.ts_code=m.ts_code WHERE s.ts_code !~ '^(200|900)' AND s.list_date<=DATE '2026-09-30' AND (s.delist_date IS NULL OR s.delist_date>DATE '2026-09-30')),q AS(SELECT count(*) member_codes,count(*) FILTER(WHERE s.fullname IS NULL OR trim(s.fullname)='') fullname_missing,count(DISTINCT nullif(trim(s.fullname),'')) distinct_fullnames,count(*) FILTER(WHERE s.curr_type IS NULL) currency_missing,count(*) FILTER(WHERE s.curr_type IS NOT NULL AND s.curr_type<>'CNY') non_cny_codes,count(*) FILTER(WHERE s.delist_date>DATE '2026-09-30' AND s.delist_date<=DATE '2026-10-30') subsequently_delisted FROM base a JOIN raw_tushare.stock_basic s ON s.ts_code=a.ts_code)
SELECT jsonb_build_object('section','cohort_identity_metadata','as_of',current_timestamp,'data',to_jsonb(q)) FROM q;
COMMIT;
